"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[8149],{312(e){e.exports=JSON.parse('{"title":"\uc18c\uc2a4\ub9f5 \ub610\ud55c \uc65c \ubcf4\uc548\uc778\uac00","date":"2026-06-09","coverUrl":"/kudzu-based-bench/assets/notion/9147385cec998ea7.png","html":"<h1 data-notion-block-id=\\"377e548d-8a8e-80fa-8b0d-e247fe656d5c\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"378e548d-8a8e-80cd-a54f-fab947b0caa0\\" id=\\"378e548d-8a8e-80cd-a54f-fab947b0caa0\\">\uc18c\uc2a4\ub9f5 \ub610\ud55c \uc65c \ubcf4\uc548\uc778\uac00</h2><a href=\\"https://neciudan.dev/everything-you-need-to-know-about-sourcemaps\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://neciudan.dev/everything-you-need-to-know-about-sourcemaps</a><p data-notion-block-id=\\"378e548d-8a8e-8035-834e-d29e66ac390d\\">\uc18c\uc2a4\ub9f5 \ub3d9\uc791 \uc6d0\ub9ac\ub97c \uc18c\uac1c\ud558\uace0, \uc65c \uc18c\uc2a4\ub9f5\uc774 \ubcf4\uc548 \uc704\ud5d8\uae4c\uc9c0 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub294\uc9c0 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub354 \uc790\uc138\ud558\uac8c, \uc778\ud130\ub809\ud2f0\ube0c \uc6f9\uacfc \ud568\uaed8 \uc774\ud574\ud558\ub824\uba74 <a href=\\"https://ones-to-watch.ethansup.net/news/post/2a2e548d-8a8e-80af-8192-fbb8ab287b78#2a2e548d-8a8e-80d1-8ccc-eadec5880dff\\">source map\uc740 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud560\uae4c</a>\ub97c, \uadf8\ub9ac\uace0 source map API\uc758 \ud45c\uc900\ud654\ub97c \uc0b4\ud3b4\ubcf4\ub824\uba74 <a href=\\"https://ones-to-watch.ethansup.net/news/post/327e548d-8a8e-807a-94c6-f8ee5a3ccbb6#328e548d-8a8e-80ca-bf34-db11b210c902\\">JS \ud45c\uc900\ud654\uc758 \uc5ec\uc815</a>\uc744 \ub354 \uc0b4\ud3b4\ubcf4\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4. \ub610\ud55c \uacf5\uae09\ub9dd \ubcf4\uc548 \uc8fc\uc81c\uc640 \ube44\uc2b7\ud558\uac8c \ud544\ud130\ub9c1 \ubc29\uc5b4 \ubc29\uc2dd\ub610\ud55c \uc81c\uc2dc\ud558\uace0 \uc788\uc73c\ubbc0\ub85c \uaf2d \uc801\uc6a9\ud588\uc73c\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"378e548d-8a8e-80f6-aa3a-dc5d5ab67495\\" id=\\"378e548d-8a8e-80f6-aa3a-dc5d5ab67495\\">Conductor\uc758 Rewrite \uc911 \ubb34\uc5c7\uc774 \uc131\ub2a5\uc744 \ub192\uc600\ub098</h2><a href=\\"https://performance.dev/the-conductor-rewrite\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://performance.dev/the-conductor-rewrite</a><p data-notion-block-id=\\"378e548d-8a8e-8037-a466-f015ba4e6b57\\">AI\ub97c \ud65c\uc6a9\ud558\ub294 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc778 Conductor\uc5d0\uc11c Rewrite\ub97c \uc9c4\ud589\ud558\uba74\uc11c \uc5b4\ub5a4 \ubd80\ubd84\uc744 \ubc14\uafd4\uc11c \uc131\ub2a5\uc744 \ub192\uc600\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uad00\ub828 \uae00\ub85c\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/327e548d-8a8e-807a-94c6-f8ee5a3ccbb6#328e548d-8a8e-8046-9063-efaf7c43e865\\">Tanstack Start\ub294 \ucc28\uc138\ub300 Next.js\uc758 \uafc8\uc744 \uafb8\ub294\uac00</a>\uacfc <a href=\\"https://ones-to-watch.ethansup.net/news/post/2bde548d-8a8e-805b-83a0-e7a11b36e1f3#2bfe548d-8a8e-8057-becf-e03feb71cdad\\">Github \uc7ac\uad6c\uc131\ud558\uae30, RSC\uc640 CSS\ub85c.</a>\ub97c \ubcf4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4. \uadf8\ub9ac\uace0 Rewrite\ud558\uba74\uc11c \uae30\ubc18\uc73c\ub85c \ub454 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\ub3c4 \uc815\ub9ac\ub418\uc5b4 \uc788\uc73c\ub2c8 \uae30\ub2a5\uc744 \ub9cc\ub4e4 \ub54c \uc5b4\ub5a4 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc368\uc57c \ud560 \uc9c0 \uace0\ubbfc\uc774\ub77c\uba74, \ubc14\uafc0 \ub54c \uace0\ubbfc\uc774\ub77c\uba74 \uc774 \ubd80\ubd84\ub3c4 \ucc38\uace0\ud558\uc2dc\uba74 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"378e548d-8a8e-8040-93f0-c0615afb8fb5\\" id=\\"378e548d-8a8e-8040-93f0-c0615afb8fb5\\">\ubaa8\ub2c8\ud130\ub9c1 \uc0c8\ub85c\uc6b4 \uac1c\ub150: TBT Window</h2><a href=\\"https://csswizardry.com/2026/06/front-ends-missing-metric-the-tbt-window/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://csswizardry.com/2026/06/front-ends-missing-metric-the-tbt-window/</a><p data-notion-block-id=\\"378e548d-8a8e-80e1-a2f2-f58333199e05\\">TBT\uac00 \ubb34\uc5c7\uc778\uc9c0, \uadf8\ub9ac\uace0 <a href=\\"https://web.dev/articles/tbt?hl=ko#tbt-inp\\">TBT\uac00 \uc678\uba74\ubc1b\ub294 \uc774\uc720</a>\ub97c \ub17c\ub9ac\uc801\uc73c\ub85c \uc124\uba85\ud558\uba74\uc11c, TBT\uac00 \uac11\uc790\uae30 \uce58\uc19f\uc740 \ud604\uc2e4 \uc608\uc2dc\uc640 \ud568\uaed8 TBT Window\uc640 TBT\ub97c \ubd84\ub9ac\ud574\uc11c \ubd10\uc57c\ud55c\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4. LCP/TTI/TBT\uc640\uc758 \uac1c\ub150, \uadf8\ub9ac\uace0 \uc5b4\ub5a4 \uc5f0\uad00\uad00\uacc4\uac00 \uc788\ub294\uc9c0, \uadf8\ub9ac\uace0 \\"\uc6d0\uc778\uc744 \uc5c6\uc560\ub294 \uac83\uc774 \ud574\uacb0\ucc45\\"\uc774 \uc544\ub2c8\ubbc0\ub85c \ud56d\uc0c1 \uc7a5\ub2e8\uc810\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc744 \ub2e4\uc2dc \uc9da\uc5b4\ubcf4\uac8c \ub418\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"378e548d-8a8e-8002-9b9f-c5bebb6c0b9d\\" id=\\"378e548d-8a8e-8002-9b9f-c5bebb6c0b9d\\">\ub354 \uac15\ud654\ub41c Auth \uac00\uc774\ub4dc\ubd81(+10\uac15)</h2><a href=\\"https://auth.pilcrowonpaper.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://auth.pilcrowonpaper.com/</a><p data-notion-block-id=\\"37ae548d-8a8e-8083-a252-c8f6de1c3ed8\\">\uc608\uc804\uc758 Lucia Auth\ub97c \ub9cc\ub4e0 Pilcrow\uac00 \ub9cc\ub4e0 <a href=\\"https://thecopenhagenbook.com/\\">Copenhagen book</a>\uc758 \uc9c4\ud654 \ubc84\uc804\uc785\ub2c8\ub2e4! \uc6f9 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \uc778\uc99d/\uc778\uac00\ub97c \uc5b4\ub5bb\uac8c \uc2e4\uc804\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294\uc9c0 go \ucf54\ub4dc\ubca0\uc774\uc2a4\ub97c \uae30\ubc18\uc73c\ub85c \ubaa8\ub450 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc <a href=\\"https://better-auth.com/blog/authjs-joins-better-auth\\">Better Auth\uc5d0 Auth.js\uac00 \ud569\ub958\ud55c \ub9cc\ud07c</a> Better Auth\uac19\uc774 \uc9c1\uc811 \uad6c\ud604\ud558\ub294 \ubc29\uc2dd\uc744 \uc120\ud638\ud558\ub294 \ud504\ub85c\uc81d\ud2b8\uac00 \ub9ce\uc544\uc9d0\uc5d0 \ub530\ub77c \ud574\ub2f9 Auth book\uc5d0\uc11c \uc5b4\ub5a4 \uac83\uc774 \uc788\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc8fc\uc758 \ud574\uc57c \ud560 \uc810\uc740 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uace0 \uc788\uc73c\uba74 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"378e548d-8a8e-806b-bfd1-ea55f4ce084d\\" id=\\"378e548d-8a8e-806b-bfd1-ea55f4ce084d\\">Diff \ube60\ub974\uac8c \ubcf4\uc5ec\uc8fc\uae30</h2><a href=\\"https://pierre.computer/writing/on-rendering-diffs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://pierre.computer/writing/on-rendering-diffs</a><p data-notion-block-id=\\"37ae548d-8a8e-80cf-ae11-daaa949ab6f5\\">\ud070 diff\ub97c \uc989\uc2dc \ub80c\ub354\ub9c1\ud558\uae30 \uc704\ud574 \uac00\uc0c1\ud654\uc758 \uae5c\ube61\ud798 \ud604\uc0c1\uc744 \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \ud765\ubbf8\ub85c\uc6b4 \ubc29\uc2dd\uc73c\ub85c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub610\ud55c \uac00\uc0c1\ud654 \uc774\uc678\uc5d0\ub3c4 \ud574\uacb0\ud574\uc57c \ud560 \ubb38\uc81c\uac00 \uc788\ub2e4\ub294 \uac83\uc744 \uc774 \uae00\uacfc <a href=\\"https://ones-to-watch.ethansup.net/news/post/33ae548d-8a8e-80c3-a070-d4a8afbf5fa6#340e548d-8a8e-80de-be71-daebdb28eb04\\">Github diff \ud654\uba74 \ucd5c\uc801\ud654</a> \uae00 \ub610\ud55c \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uae00\uacfc \uc5f0\uacb0\ub41c \uae00, \uc5f0\uacb0\ub41c \uae00\uc758 part 1 \uae00 \ub610\ud55c \uc18c\uac1c\ud558\ub4ef\uc774 \uac00\uc0c1\ud654\uac00 \uac00\uc7a5 \uc5b4\ub824\uc6b4 \ubd80\ubd84\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"378e548d-8a8e-80ca-9b80-d8f50bef2a80\\" id=\\"378e548d-8a8e-80ca-9b80-d8f50bef2a80\\">Stream \ubc31\ud504\ub808\uc154 \uc0ac\uc6a9 \uc548\ub0b4\uc11c</h2><a href=\\"https://frontendmasters.com/blog/your-node-js-streams-arent-backpressuring-theyre-silently-eating-your-memory/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/your-node-js-streams-arent-backpressuring-theyre-silently-eating-your-memory/</a><a href=\\"https://frontendmasters.com/blog/the-production-playbook-for-node-js-stream-leaks/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/the-production-playbook-for-node-js-stream-leaks/</a><p data-notion-block-id=\\"37ae548d-8a8e-80a0-b887-cf612c25e9a6\\"><a href=\\"https://nodejs.org/learn/modules/backpressuring-in-streams\\">Backpressure</a>(\uc18c\ube44\uc790\uac00 \uc0dd\uc0b0\uc790\uc5d0\uac8c \uc18d\ub3c4\ub97c \uc904\uc5ec\ub77c\ub77c\uace0 \ubcf4\ub0b4\ub294 \uc2e0\ud638)\ub97c \ud604\uc2e4\uc5d0\uc11c \uc9da\uc73c\uba74 \uc5b4\ub5a4 \ubd80\ubd84\uc774 \ubb38\uc81c\uac00 \ub418\ub294\uc9c0, \uadf8\ub9ac\uace0 \ud504\ub85c\ub355\uc158\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc368\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Node.js \uc2a4\ud2b8\ub9bc\uc744 \uc0ac\uc6a9\ud558\uace0 \uc788\ub2e4\uba74 \uae4a\uac8c \ud30c\ubcfc\ub9cc\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"377e548d-8a8e-80d4-8ddd-d77b13d09911\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"378e548d-8a8e-80ec-861a-cce91e9dd6fd\\" id=\\"378e548d-8a8e-80ec-861a-cce91e9dd6fd\\">\ucd5c\uace0\uc758 \ub85c\ub529 \uc0c1\ud0dc\ub294 \ub85c\ub529\uc774 \uc5c6\ub294 \uac83</h2><a href=\\"https://jjenzz.com/best-loading-states-are-no-loading-states/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jjenzz.com/best-loading-states-are-no-loading-states/</a><p data-notion-block-id=\\"377e548d-8a8e-8080-a991-d858ad25ea03\\">\ube48 UI\ub97c \ubc84\uadf8\uac00 \uc544\ub2c8\ub77c \uc2e0\ud638\ub85c \ubcf8\ub2e4\ub294 \uad00\uc810\uc744 \ud480\uc5b4\ub0b8 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/36be548d-8a8e-800f-be7a-f6849a670533#36be548d-8a8e-800b-8d91-d4b09d3e50e1\\">\ube60\ub978 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc740 \ucd5c\uc2e0 \ub370\uc774\ud130\ub97c \ubcf4\uc5ec\uc8fc\uc9c0 \uc54a\ub294\ub2e4.</a>\uc640 \ube44\uc2b7\ud558\uac8c \ud480\uc5b4\ub0b8 \uae00\uc774\ub77c \ub2e4\uc2dc \ud55c \ubc88 \uac1c\ub150\uc744 \uc7a1\ub294\ub370 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"377e548d-8a8e-80f4-a278-f67a2a6b5ed8\\" id=\\"377e548d-8a8e-80f4-a278-f67a2a6b5ed8\\"><code>blocking=\\"render\\"</code>\ub85c \uc758\ub3c4\uc801\uc73c\ub85c \ub80c\ub354\ub9c1 \ub9c9\uae30</h2><a href=\\"https://www.jayfreestone.com/writing/intentional-render-blocking-javascript/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.jayfreestone.com/writing/intentional-render-blocking-javascript/</a><p data-notion-block-id=\\"377e548d-8a8e-8019-8fba-d64966f68341\\"><code>blocking=\\"render\\"</code>\ub97c \uac04\ub2e8\ud558\uac8c \uc18c\uac1c\ud558\ub294 \uae00(<a href=\\"https://ones-to-watch.ethansup.net/news/post/237e548d-8a8e-80c8-8e59-c60afe0411ca#23de548d-8a8e-8062-969c-d6d39c0553db\\">\uc131\ub2a5 \ucd5c\uc801\ud654 \ub9ac\uc2a4\ud2b8\uc758 \uc11c\ube0c \uae00</a>)\uc5d0\uc11c\ub294 \uc18d\uc131\uc774 \ubb34\uc5c7\uc778\uc9c0\ub9cc \uc18c\uac1c\ud558\ub294 \uae00\uc774\uc600\ub2e4\uba74, \uc774 \uae00\uc5d0\uc11c\ub294 \uc5b4\ub514\uc5d0 \uc0ac\uc6a9\ud574\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"37ae548d-8a8e-80e6-8c67-cc51bdfac7c0\\" id=\\"37ae548d-8a8e-80e6-8c67-cc51bdfac7c0\\">Expo\uc5d0\uc11c \ubc30\uc6b4 \uad50\ud6c8\ub4e4</h2><a href=\\"https://evanbacon.dev/blog/expo\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://evanbacon.dev/blog/expo</a><p data-notion-block-id=\\"378e548d-8a8e-80f9-b628-c238110c456d\\">\uae30\uc220\uc801\uc778 \ud68c\uace0\ub294 \uc544\ub2c8\uc9c0\ub9cc \ubaa8\ub4e0 \uc81c\ud488(\uc0ac\ub0b4 \uc81c\ud488\uc5d0\ub3c4!)\uc5d0 \uc801\uc6a9\ud560\ub9cc\ud55c \uc6d0\uce59\ub4e4\uc744 \uc18c\uac1c\ud558\ubbc0\ub85c \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"377e548d-8a8e-80e9-9e03-cf9a67ab8897\\" id=\\"377e548d-8a8e-80e9-9e03-cf9a67ab8897\\">CSS\ub9cc\uc73c\ub85c \ub9cc\ub4dc\ub294 \ud328\ub7f4\ub799\uc2a4 \ud6a8\uacfc</h2><a href=\\"https://dan-webnotes.com/posts/2026-06-02-css-native-parallax-effect/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dan-webnotes.com/posts/2026-06-02-css-native-parallax-effect/</a><p data-notion-block-id=\\"37ae548d-8a8e-8047-b718-c0dfb691277b\\">\uc2a4\ud06c\ub864 \uc774\ubca4\ud2b8 \ub9ac\uc2a4\ub108 \uc5c6\uc774 CSS \uc2a4\ud06c\ub864 \uae30\ubc18 \uc560\ub2c8\uba54\uc774\uc158(<code>view-timeline</code>)\ub9cc\uc73c\ub85c \ud328\ub7f4\ub799\uc2a4\ub97c \uad6c\ud604\ud558\ub294 \uc720\ud2f8 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"378e548d-8a8e-8026-b2b5-c8dda8f20b66\\" id=\\"378e548d-8a8e-8026-b2b5-c8dda8f20b66\\">tsgo\uac00 \uba54\ubaa8\ub9ac\ub97c \ub108\ubb34 \ub9ce\uc774 \uc4f4\ub2e4</h2><a href=\\"https://zackoverflow.dev/writing/why-does-tsgo-use-so-much-memory\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://zackoverflow.dev/writing/why-does-tsgo-use-so-much-memory</a><h2 data-notion-block-id=\\"378e548d-8a8e-803f-bd21-e49733781d02\\" id=\\"378e548d-8a8e-803f-bd21-e49733781d02\\">\ud30c\uc77c \uc5c5\ub85c\ub4dc \uc18d\uc131\uc740 UX\uc5d0 \uc88b\uc740 \uac78\uae4c</h2><a href=\\"https://adamsilver.io/blog/why-the-accept-attribute-degrades-file-upload-ux/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://adamsilver.io/blog/why-the-accept-attribute-degrades-file-upload-ux/</a><h2 data-notion-block-id=\\"37ae548d-8a8e-80b4-9424-c489df4c7218\\" id=\\"37ae548d-8a8e-80b4-9424-c489df4c7218\\">Vercel \ub514\uc790\uc778 \ud300\uc758 AI \uc6cc\ud06c\ud50c\ub85c\uc6b0</h2><a href=\\"https://www.hannahhearth.com/posts/tools-the-vercel-product-design-team-actually-uses\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.hannahhearth.com/posts/tools-the-vercel-product-design-team-actually-uses</a><h1 data-notion-block-id=\\"377e548d-8a8e-80e8-a5ca-f143af7ba80b\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://stately.ai/docs/xstate-store\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://stately.ai/docs/xstate-store</a><p data-notion-block-id=\\"377e548d-8a8e-807a-bc20-d8529d66aa02\\">Zustand\xb7Redux \ub300\uc548\uc778 \uac00\ubcbc\uc6b4 \uc774\ubca4\ud2b8 \uae30\ubc18 \uc0c1\ud0dc \uad00\ub9ac \ub77c\uc774\ube0c\ub7ec\ub9ac @xstate/store\uac00 4\ubc84\uc804\uc744 \ub0b4\uba74\uc11c Standard Schema(Zod \ub4f1) \uc9c0\uc6d0\uacfc atom\uc774 \ucd94\uac00\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://tanstack.com/blog/start-adds-rsbuild-support\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/blog/start-adds-rsbuild-support</a><p data-notion-block-id=\\"377e548d-8a8e-80eb-bf27-f138055be946\\">TanStack Start\uac00 Vite\uc5d0 \ub354\ud574 Rspack \uae30\ubc18 Rsbuild\ub97c 1\uae09 \ube4c\ub4dc \uc635\uc158\uc73c\ub85c \uc9c0\uc6d0\ud558\uac8c \ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://motion.dev/docs/arc\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://motion.dev/docs/arc</a><p data-notion-block-id=\\"377e548d-8a8e-8020-a025-c7aa64943717\\">Motion\uc5d0 \ub450 \uc810 \uc0ac\uc774\ub97c \uace1\uc120\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 <code>arc()</code>\uac00 \ucd94\uac00\ub418\uc5b4, \uc9c1\uc120 \ubcf4\uac04\uc774 \uc5b4\ub824\uc6b4 \ub808\uc774\uc544\uc6c3 \uc560\ub2c8\uba54\uc774\uc158\xb7\uacf5\uc720 \uc694\uc18c \uc804\ud658\uc5d0\ub3c4 \uace1\uc120\uc744 \uc785\ud790 \uc218 \uc788\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://replacements.fyi/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://replacements.fyi/</a><p data-notion-block-id=\\"377e548d-8a8e-8052-ab40-f65614fca61f\\">\ud328\ud0a4\uc9c0 \uc774\ub984\uc744 \uc785\ub825\ud558\uba74 \ub354 \uac00\ubccd\uace0 \uc548\uc804\ud55c \ub300\uc548\uc744 \uc54c\ub824\uc8fc\uace0 <code>package.json</code>\uae4c\uc9c0 \uc2a4\uce94\ud574\uc8fc\ub294 e18e.dev\uc758 \uc11c\ube44\uc2a4\uc785\ub2c8\ub2e4.</p><a href=\\"https://specification.website/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://specification.website/</a><p data-notion-block-id=\\"377e548d-8a8e-80be-8a90-e4b30c93c426\\">\uc88b\uc740 \uc6f9\uc0ac\uc774\ud2b8\uac00 \uac16\ucdb0\uc57c \ud560 \uae30\uc220 \uc694\uac74\uc744 SEO\xb7\uc811\uadfc\uc131\xb7\ubcf4\uc548\xb7\uc131\ub2a5 \ub4f1 128\uac1c \ud56d\ubaa9\uc73c\ub85c \uc815\ub9ac\ud558\uace0 \uac01 \ud56d\ubaa9\uc744 \ud45c\uc900 \ucd9c\ucc98\uc640 \uc5f0\uacb0\ud574\uc8fc\ub294 \ud50c\ub7ab\ud3fc \ubb34\uad00 \uba85\uc138\uc785\ub2c8\ub2e4.</p>"}')}}]);